/* Example of a style block */
<style>
  /* CSS rules will go here */
</style>

/* Example: styling a button's hover state */
button:hover {
  background-color: #007bff;
  color: white;
}

/* Similar: adding more properties to a selector */
button {
  color: blue;
  font-size: 16px;
  font-weight: bold;
  background-color: lightblue;
}

/* Similar: another pseudo-element rule */
::placeholder {
  color: gray;
}

/* Example: styling selected text */
::selection {
    background-color: yellow;
    color: black;
}

/* Similar: adding more properties to a CSS rule */
.example {
  color: blue;
  font-size: 16px;
  text-shadow: 1px 1px 2px black;
  cursor: pointer;
}
